ecc_agent_script_include.script:
ms.include("IllumioMIDConstants");
var IllumioUpdateWorkloads = Class.create();

IllumioUpdateWorkloads.prototype = {
    VALID_IP_REGEX: /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
    initialize: function() {
        // Constructed before the job id is read below, so it starts contextless and is given the
        // context as soon as there is one. See setContext in IllumioLogUtil.
        this.logger = new IllumioLogUtil(null, 'IllumioUpdateWorkloads');
        this.SNOWusername = ms.getConfigParameter("mid.instance.username");
        this.SNOWpassword = ms.getConfigParameter("mid.instance.password");
        this.SNOWurl = String(ms.getConfigParameter("url"));
        if (this.SNOWurl[this.SNOWurl.length - 1] === '/') {
            this.SNOWurl = this.SNOWurl.substring(0, this.SNOWurl.length - 1);
        }
        this.jobSysId = probe.getParameter('glide.jms.jobSysId');
        this.logger.setContext(this.jobSysId);
        this.partialSucc = probe.getParameter('glide.jms.partialSucc');

        // added for bifurcation for sync of the workload payload
        this.autoSync = probe.getParameter('glide.jms.autoSync');
        // R33: the row sys_ids are no longer in the message. _payloadRowSysIds() queries the
        // payload table for jobSysId instead. This is what the instance says it wrote, kept only
        // so a mismatch between "written" and "found" can be logged.
        this.payloadRows = parseInt(probe.getParameter('glide.jms.payloadRows'), 10);
        this.configSysId = probe.getParameter('glide.jms.configSysId');

        this.skipped = probe.getParameter('glide.jms.skipped');
        this.count = probe.getParameter('glide.jms.count');

        this.payload = probe.getParameter('glide.jms.payload');
        this.pceUrl = probe.getParameter('glide.jms.pce_url');
        this.pceAuthorization = probe.getParameter('glide.jms.pce_authorization');
        this.pceOrgId = probe.getParameter('glide.jms.pce_org_id');
        this.pceMIDProxy = probe.getParameter('glide.jms.enable_pce_mid_proxy');

        // Guarded the same way IllumioManageAsyncJobs guards `glide.jms.chunk_size`, and for the
        // same reason. `parseInt` with no radix, no fallback and no `< 1` check turned a missing
        // or junk parameter into `batchSize = NaN`, and NaN is the worst possible value here
        // because it fails SILENTLY rather than throwing. Every chunking loop in this file has
        // the shape `for (i = 0; i < len; i += this.batchSize)`: the first pass takes
        // `slice(0, NaN)`, which is `slice(0, 0)` -- an EMPTY chunk -- and then `i += NaN` makes
        // `i` NaN, `NaN < len` is false, and the loop ends. One empty chunk, PUT to the PCE as an
        // empty body, and the run reports success having synced nothing.
        //
        // DEFAULT_MID_BATCH_SIZE, not a literal, so this and IllumioManageAsyncJobs cannot drift.
        // A MID script include has no `gs` and cannot read the system property the instance sets,
        // so the number is duplicated by hand from BATCH_SIZE_STANDARD in IllumioConstants -- see
        // the note on the constant. Divergence is not fatal: it only changes the chunk size on a
        // run whose ECC message was already malformed.
        this.batchSize = parseInt(probe.getParameter('glide.jms.batch_size'), 10) ||
            DEFAULT_MID_BATCH_SIZE;
        if (this.batchSize < 1) {
            this.logger._warning(
                "Invalid 'x_illu2_illumio.batch_size_standard' provided. Proceeding with " +
                DEFAULT_MID_BATCH_SIZE +
                " as default value. Please set a valid value to " +
                "'x_illu2_illumio.batch_size_standard' property."
            );
            this.batchSize = DEFAULT_MID_BATCH_SIZE;
        }

        // `workloads_to_delete` and `vens_to_unpair` used to be read here. R33 moved the delete
        // branch onto the deletion payload table -- see _payloadRowSysIds -- and no sender puts
        // them in the message any more. Removed rather than left assigned: a parameter that is
        // read but never used reads like a live input, and this one survived the rewrite long
        // enough to hide that IllumioDeletionHandler was still sending the payload inline to a
        // branch that had stopped looking at it.

        this.fieldMappings = probe.getParameter('glide.jms.fieldMappings');

        this.timeZone = probe.getParameter('glide.jms.time_zone');
        this.SimpleDF = Packages.java.text.SimpleDateFormat;
        this.TimeZone = Packages.java.util.TimeZone;

        this.snowDateFormat = this.SimpleDF("yyyy-MM-dd HH:mm:ss");
        this.illumioDateFormat = this.SimpleDF("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");

        this.snowDateFormat.setTimeZone(this.TimeZone.getTimeZone('GMT'));
        this.illumioDateFormat.setTimeZone(this.TimeZone.getTimeZone('UTC'));



        // Table Names


        this.newLabelsCreated = {};

        // R13 (commented, not deleted). Both assigned here and read nowhere in this file or any
        // other MID script include -- the comment above them just said "Mapping", which is what
        // kept them looking load-bearing. They are of a piece with the label reverse-lookup R34
        // commented out (collectLabelDetails / labelDetails): that was the code that would have
        // filled them. `newLabelsCreated` above is live and is NOT part of this -- it is what
        // the label creation path actually writes to.
        // this.pceLabels = {};
        // this.selectLabels = {};

        this.created = true;
        this.updatedManaged = true;
        this.updatedUnManaged = true;
        // R34: the href -> {key, value} reverse lookup. Run-long and never cleared -- filled
        // once, unfiltered, from a ~100k-row table (PCE_LABELS_MAPPING_TABLE), and held for the
        // life of the probe across every payload row. Objective 3's only leak.
        //
        // Removed rather than windowed, because its sole consumer was `payloadPut`, which
        // nothing has ever read (see the note on snowUpdateObject in create()). The MID needs no
        // label data FROM ServiceNow: the payload arrives with `labels` and `createlabels`
        // already resolved by the instance, and nothing is written back -- post-sync discovery
        // rebuilds the mapping table wholesale.
        // this.labelDetails = new Object();
        this.operation = probe.getParameter('glide.jms.operation');

        this.utils = new IllumioPCEUtils(this.timeZone, this.jobSysId);
        this.protocol = this.utils.getPortFromUrl(this.pceUrl);

        this.retryParams = DEFAULT_RETRY_PARAMS;
        try {
            this.retryParams = JSON.parse(probe.getParameter('glide.jms.retry_params'));
        } catch (e) {
            this.logger._except('IllumioUpdateWorkloads - Cannot parse the JSON of retry parameters');
        }

        var decodedAuth = this.utils.decodeBase64(this.pceAuthorization);
        decodedAuth = decodedAuth.split(":");
        this.pceUsername = decodedAuth[0];
        this.pcePassword = decodedAuth.slice(1).join(':');

        this.pceHttpClient = new IllumioHTTPClient(this.pceUrl, this.pceUsername, this.pcePassword, this.protocol, this.pceMIDProxy, this.retryParams, this.jobSysId);
        this.snHttpClient = new IllumioHTTPClient(this.SNOWurl, this.SNOWusername, this.SNOWpassword, "443", null, this.retryParams, this.jobSysId);
    },

    /**
     * " (12.34s)" -- the trailing duration every timed log line in the application ends with.
     *
     * Same contract as IllumioSyncUtils.since and IllumioDiscoveryUtils.formatDuration on the
     * instance: a per-STEP duration, two decimal places, in round brackets at the END of the
     * line. Duplicated rather than shared because a MID script include cannot reach instance
     * code -- see the note in IllumioMIDConstants. The three copies must not drift.
     *
     * @param {Number} startedAt Epoch milliseconds the step began
     * @returns {String} Clause to append to a log line
     */
    _since: function(startedAt) {
        return ' (' + ((new Date().getTime() - startedAt) / 1000).toFixed(2) + 's)';
    },

    /**
     * The sys_ids of this job's payload rows, in the order they were written.
     *
     * R33. These used to arrive in the ECC message as a comma-separated parameter, which became a
     * single XML attribute that grew with the run: one row per 500-workload window put ~4,000
     * sys_ids, ~132 KB, into one attribute on a 2M-workload sync, and shrinking the window made it
     * worse. The rows carry a reference to the job, so the MID can ask for them instead and the
     * message carries one sys_id whatever the run size.
     *
     * The sys_ids are collected up front rather than the caller iterating this cursor directly,
     * because the caller DELETES each row as it consumes it -- walking a cursor over a table while
     * deleting out of it is how rows get skipped. Collecting first also costs nothing that matters:
     * this is the list that used to be in the message, ~132 KB at the largest run size, and MID
     * heap was never the constraint.
     *
     * Ordered by creation so rows are consumed in the order phase 2 produced them. Nothing depends
     * on that -- each row is an independent window of workloads -- but an unordered walk makes the
     * job log read as if work were happening at random.
     *
     * @param {String} payloadTable Payload table to read
     * @returns {Array} Row sys_ids, empty when the job wrote none
     */
    _payloadRowSysIds: function(payloadTable) {
        var sysIds = [];

        if (!this.jobSysId) {
            this.logger._error('[IllumioUpdateWorkloads] No jobSysId on the probe, so the ' +
                payloadTable + ' rows for this run cannot be found.');
            return sysIds;
        }

        // Over the Table API, not GlideRecord. This code runs on the MID Server host, which has
        // no database and no GlideRecord class -- every other instance read in this file goes
        // through snHttpClient for exactly that reason (_checkInvalidatedJob, _updateJobRecord,
        // checkCancelledJobStatus, and the deleteMethod that retires each row below). A
        // GlideRecord here threw ReferenceError on the first row, which the operation's own
        // try/catch turned into a job marked `failed` with no workloads touched and every
        // payload row still sitting in the table.
        //
        // `^` is percent-encoded by hand: the endpoint string is handed to the HTTP method
        // unchanged, so an unencoded caret is a query separator the Table API will not see.
        var query = PAYLOAD_JOB_FIELD + '=' + this.jobSysId + '%5EORDERBYsys_created_on';
        var url = TABLE_API + payloadTable +
            '?sysparm_fields=sys_id' +
            '&sysparm_limit=' + PAYLOAD_ROW_QUERY_LIMIT +
            '&sysparm_query=' + query;

        var response = this.snHttpClient.get(url, '');

        if (response.hasError || !response.data || !response.data.result) {
            this.logger._error('[IllumioUpdateWorkloads] Could not read the ' + payloadTable +
                ' rows for job ' + this.jobSysId + '. Status: ' + response.status);
            return sysIds;
        }

        var rows = response.data.result;
        for (var i = 0; i < rows.length; i++) {
            sysIds.push(rows[i].sys_id + '');
        }

        // The instance told us how many it wrote. A mismatch means rows were lost between the
        // insert and now, or PAYLOAD_JOB_FIELD does not match the column the instance stamped --
        // both of which otherwise surface as a sync that silently does less than it reported.
        if (!isNaN(this.payloadRows) && this.payloadRows !== sysIds.length) {
            this.logger._error('[IllumioUpdateWorkloads] The instance wrote ' + this.payloadRows +
                ' payload row(s) to ' + payloadTable + ' for job ' + this.jobSysId + ' but ' +
                sysIds.length + ' were found. Check that the "' + PAYLOAD_JOB_FIELD +
                '" column exists and matches IllumioSyncUtils.PAYLOAD_JOB_FIELD.');
        }

        return sysIds;
    },

    /**
     * One payload row's contents, parsed, or null if it could not be read.
     *
     * Fetched a row at a time rather than pulling every row's `payload` in the sys_id query
     * above. The whole point of splitting the run across rows is that only one window of
     * workloads is in memory at once; asking for all the payloads together would put the entire
     * run back in a single response and undo it.
     *
     * @param {String} payloadTable Payload table the row lives in
     * @param {String} rowSysId     sys_id of the row
     * @returns {Object} Parsed payload, or null
     */
    _readPayloadRow: function(payloadTable, rowSysId) {
        var url = TABLE_API + payloadTable + '/' + rowSysId + '?sysparm_fields=payload';
        var response = this.snHttpClient.get(url, '');

        if (response.hasError || !response.data || !response.data.result) {
            this.logger._error('[IllumioUpdateWorkloads] Could not read the ' + payloadTable +
                ' row ' + rowSysId + '. Status: ' + response.status);
            return null;
        }

        // A sys_id GET returns the record as an object, not a one-element array like a query.
        var record = response.data.result;
        if (!record.payload) {
            this.logger._error('[IllumioUpdateWorkloads] The ' + payloadTable + ' row ' +
                rowSysId + ' has an empty payload.');
            return null;
        }

        return JSON.parse(record.payload);
    },

    /**
     * Probe entry point.
     *
     * W5/W6: the body is _run(). This wrapper exists for two things the body cannot do for
     * itself.
     *
     * W6 -- one boundary line the moment the probe starts, pushed to the instance rather than
     * left in agent0.log. A transport failure (MID offline, the message never picked up, a probe
     * name that does not resolve) runs none of our code, so nothing inside here can report it.
     * The instance logging "queued for the MID" with no probe-entered line after it is what
     * says the break is in the transport and not in either half.
     *
     * W5 -- the push budget for this run is reset here, before the milestone below, or that line
     * would be charged against whatever the previous run in this MID JVM spent. There is nothing
     * to do at the end: each line is pushed to the instance as it happens, so a run that throws
     * has already delivered the errors that led up to the throw.
     */
    run: function() {
        this.logger.resetPushBudget();
        this.logger._milestone('Probe entered.');
        return this._run();
    },

    _run: function() {
        var jobContent;
        try {
            this.payload = decodeURI(this.payload);
        } catch (e) {
            // if we get malformed URI sequence, we skip it, else, we throw any other error
            if (e.message.search(/Malformed URI sequence/i) < 0) {
                throw new Error("Unhandled error - " + e.message);
            }
        }

        // Call respective method according to the operation requested
        if (this.operation == "update") {
            try {
                var updateResult = this.update(this.payload);
                var payloadToUpdate = JSON.parse(this.payload);

                if (!updateResult) {
                    this.logger._debug("[update]: Job is cancelled");
                    return;
                }

                if (updateResult.count && updateResult.count != 0) {
                    jobContent = {
                        job_status: JOB_STATUS_COMPLETED,
                        logs: 'Updated ' + payloadToUpdate[0].hostname + ' workload on PCE and ServiceNow',
                        current_operation: 'Updated ' + payloadToUpdate[0].hostname + ' workload on PCE',
                        job_completed: this.snowDateFormat.format(new Date()) + ""
                    };
                    this._updateJobRecord(this.jobSysId, jobContent);
                } else {
                    jobContent = {
                        job_status: JOB_STATUS_FAILED,
                        logs: 'Failed to update ' + payloadToUpdate[0].hostname + ' workload on ' + updateResult.exception,
                        job_completed: this.snowDateFormat.format(new Date()) + ""
                    };
                    this._updateJobRecord(this.jobSysId, jobContent);
                }
            } catch (exception) {
                this.logger._except("IllumioUpdateWorkloads: Exception while updating workload on PCE : " + exception);
                jobContent = {
                    job_status: JOB_STATUS_FAILED,
                    logs: "Exception while updating workload on PCE : " + exception,
                    job_completed: this.snowDateFormat.format(new Date()) + "",
                };
                this._updateJobRecord(this.jobSysId, jobContent);
            }
        }


        if (this.operation == "create") {
            try {
                var createResult = this.create(this.payload);
                var payloadToCreate = JSON.parse(this.payload);

                if (!createResult) {
                    this.logger._debug("[create]: Job is cancelled");
                    return;
                }

                if (createResult.count && createResult.count != 0) {
                    jobContent = {
                        job_status: JOB_STATUS_COMPLETED,
                        logs: 'Created ' + payloadToCreate[0].hostname + ' workload on PCE',
                        current_operation: 'Created ' + payloadToCreate[0].hostname + ' workload on PCE',
                        job_completed: this.snowDateFormat.format(new Date()) + ""
                    };
                    this._updateJobRecord(this.jobSysId, jobContent);
                } else {
                    jobContent = {
                        job_status: JOB_STATUS_FAILED,
                        logs: 'Failed to create ' + payloadToCreate[0].hostname + ' workload on ' + createResult.exception,
                        job_completed: this.snowDateFormat.format(new Date()) + ""
                    };
                    this._updateJobRecord(this.jobSysId, jobContent);
                }
            } catch (exception) {
                this.logger._except("IllumioUpdateWorkloads: Exception while creating workload on PCE : " + exception);
                jobContent = {
                    job_status: JOB_STATUS_FAILED,
                    logs: "Exception while creating workload on PCE : " + exception,
                    job_completed: this.snowDateFormat.format(new Date()) + "",
                };
                this._updateJobRecord(this.jobSysId, jobContent);
            }
        }


        if (this.operation == "updateCreate") {
            this.logger._debug("Type : updateCreate");
            // R34: was an unfiltered, unprojected, unlimited GET of the whole PCE Labels Mapping
            // table for this configuration -- ~100k rows in production -- issued ONCE here,
            // outside the payload-row loop, so it could not be windowed by construction. Only
            // the Table API's 10,000-row default kept it from landing whole on the MID heap.
            // Its result fed getLabelDetails, which fed payloadPut, which nothing reads.
            // this.collectLabelDetails();
            try {

                var unknownWorkloads, managedWorkloads, unmanagedWorkloads;
                var totalWorkloads = 0;
                var createdUnknownWorkloads = 0,
                    updatedManagedWorkloads = 0,
                    updatedUnManagedWorkloads = 0,
                    skippedWorkloads = 0;
                var deletedWorkloads = 0;
                var unpairedVens = 0;
                var payload;

                // Queried by job rather than read out of the ECC message. Empty on the
                // non-autosync branch, which never enters the loop body that uses it.
                var totalSysIds = this.autoSync == 'true' ?
                    this._payloadRowSysIds(AUTOSYNC_PAYLOAD_TABLE) : [];
                var counter = 0;

                if (this.autoSync == 'true' && totalSysIds.length === 0) {
                    this.logger._error('[updateCreate] No payload rows found for job ' +
                        this.jobSysId + '. Nothing to send to the PCE.');
                    this._updateJobRecord(this.jobSysId, {
                        job_status: JOB_STATUS_FAILED,
                        logs: 'No payload rows could be found for this job, so nothing was sent ' +
                            'to the PCE. The workloads were prepared but the MID Server could ' +
                            'not read them back.',
                        job_completed: this.snowDateFormat.format(new Date()) + ''
                    });
                    return;
                }
                // Same unit as the deletion branch below: a batch is a payload row. On the
                // non-autosync path the whole run arrives in the ECC message as a single payload,
                // which is one batch.
                var totalBatches = this.autoSync == 'true' ? totalSysIds.length : 1;
                var syncStartedAt = new Date().getTime();
                var batchLabel, rowStartedAt, rowBefore;

                do {
                    batchLabel = 'Batch ' + (counter + 1) + '/' + totalBatches;
                    rowStartedAt = new Date().getTime();
                    rowBefore = createdUnknownWorkloads + updatedManagedWorkloads +
                        updatedUnManagedWorkloads;

                    if (this.autoSync == 'true') {

                        payload = this._readPayloadRow(
                            AUTOSYNC_PAYLOAD_TABLE, totalSysIds[counter]);

                        if (payload) {
                            var deletePayloadUrl =
                                TABLE_API +
                                AUTOSYNC_PAYLOAD_TABLE +
                                '/' +
                                totalSysIds[counter];
                            this.snHttpClient.deleteMethod(
                                deletePayloadUrl,
                                ''
                            );
                            counter++;
                        } else {
                            // _readPayloadRow has already said why. Left in the table on purpose:
                            // a row that could not be read is the one row worth keeping for
                            // whoever has to work out what happened.
                            //
                            // Logged as a batch rather than passed over silently: the numbering
                            // runs to totalBatches either way, and a gap would read as a lost
                            // line.
                            this._updateJobRecord(this.jobSysId, {
                                logs: batchLabel + ': skipped, payload row could not be read'
                            });
                            counter++;
                            continue;
                        }

                    } else {
                        payload = JSON.parse(this.payload);
                    }
                    var count = parseInt(this.count);

                    if (payload.createUnknown) {
                        if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }

                        totalWorkloads = totalWorkloads + payload.createUnknown.length;
                        // If there are unknown workloads to create
                        // R34: passed as the array itself. This used to be
                        // JSON.stringify(payload.createUnknown), which create() immediately
                        // JSON.parse'd back into a second identical array -- three live copies
                        // of the bucket (original, string, reparse) at the call boundary, for
                        // no gain. create() accepts either form.
                        unknownWorkloads = payload.createUnknown;
                        // Syslog. This is one of three sub-operations within a row; the job
                        // record's unit is the row, reported once at the end of the loop body.
                        this.logger._debug('Creating ' + payload.createUnknown.length +
                            ' unknown workload(s)');
                        this._updateJobRecord(this.jobSysId, {
                            current_operation: 'Creating unknown workloads (' + batchLabel + ')'
                        });
                        var createdResult = this.create(unknownWorkloads);
                        if (!createdResult) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }

                        if (createdResult.count) {
                            createdUnknownWorkloads = createdUnknownWorkloads + createdResult.count;
                        }
                        this._logDrops('create', 'unknown workload(s)',
                            payload.createUnknown.length, createdResult);
                    }

                    if (payload.updateManaged) {

                        if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }

                        totalWorkloads = totalWorkloads + payload.updateManaged.length;
                        // If there are managed workloads to update
                        // Syslog. This is one of three sub-operations within a row; the job
                        // record's unit is the row, reported once at the end of the loop body.
                        this.logger._debug('Total critical label groups fetched: ' + count +
                            '. Updating ' + payload.updateManaged.length + ' managed workload(s)');
                        this._updateJobRecord(this.jobSysId, {
                            current_operation: 'Updating managed workloads (' + batchLabel + ')'
                        });
                        // R34: the array itself, not a stringify/re-parse round trip. See the
                        // note on createUnknown above.
                        managedWorkloads = payload.updateManaged;
                        var updatedManagedResult = this.update(managedWorkloads);
                        if (!updatedManagedResult) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }

                        if (updatedManagedResult.count) {
                            updatedManagedWorkloads = updatedManagedWorkloads + updatedManagedResult.count;
                        }
                        this._logDrops('update', 'managed workload(s)',
                            payload.updateManaged.length, updatedManagedResult);
                    }


                    if (payload.updateUnManaged) {

                        if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }

                        totalWorkloads = totalWorkloads + payload.updateUnManaged.length;
                        // If there are ummanaged workloads to update
                        // Syslog. This is one of three sub-operations within a row; the job
                        // record's unit is the row, reported once at the end of the loop body.
                        this.logger._debug('Total critical label groups fetched: ' + count +
                            '. Updating ' + payload.updateUnManaged.length +
                            ' unmanaged workload(s)');
                        this._updateJobRecord(this.jobSysId, {
                            current_operation: 'Updating unmanaged workloads (' + batchLabel + ')'
                        });
                        // R34: the array itself, not a stringify/re-parse round trip. See the
                        // note on createUnknown above.
                        unmanagedWorkloads = payload.updateUnManaged;
                        var updatedUnManagedResult = this.update(unmanagedWorkloads);
                        if (!updatedUnManagedResult) {
                            this.logger._debug("[updateCreate]: Job is cancelled");
                            return;
                        }
                        if (updatedUnManagedResult.count) {
                            updatedUnManagedWorkloads = updatedUnManagedWorkloads + updatedUnManagedResult.count;
                        }
                        this._logDrops('update', 'unmanaged workload(s)',
                            payload.updateUnManaged.length, updatedUnManagedResult);
                    }

                    // The row's one line, replacing the up-to-three unnumbered lines this loop
                    // used to write per row. Attempted is the row's own total; succeeded is the
                    // run total's movement across this iteration, which is how the three
                    // sub-operations are collapsed into one ratio without a fourth counter.
                    var rowAttempted = (payload.createUnknown ? payload.createUnknown.length : 0) +
                        (payload.updateManaged ? payload.updateManaged.length : 0) +
                        (payload.updateUnManaged ? payload.updateUnManaged.length : 0);
                    var rowSucceeded = createdUnknownWorkloads + updatedManagedWorkloads +
                        updatedUnManagedWorkloads - rowBefore;

                    // W2: per-batch, so syslog rather than the job record. It is one line per
                    // payload row, which on a large run is what turned the job log into a trace
                    // nobody could read -- and the closing Summary below already carries the
                    // totals these lines add up to. Progress stays visible on the form through
                    // current_operation, which names the batch it is on.
                    //
                    // _milestone rather than _info because this has to reach the instance: moving
                    // detail OUT of the job log is only an improvement if it lands somewhere
                    // reachable from there. Bounded by row count, not by workload count.
                    this.logger._milestone(batchLabel + ': ' + rowSucceeded + '/' + rowAttempted +
                        ' synced' + this._since(rowStartedAt));

                } while (counter < totalSysIds.length && this.autoSync == 'true');

                var skippedWl = parseInt(this.skipped);

                this.logger._debug("IllumioUpdateWorkloads: Number of workloads skipped due to critical labels: " + this.skipped);
                this.logger._debug("IllumioUpdateWorkloads: Total workloads to sync: " + totalWorkloads);
                this.logger._debug("IllumioUpdateWorkloads: createdUnknownWorkloads: " + createdUnknownWorkloads + " updatedManagedWorkloads: " + updatedManagedWorkloads + " updatedUnManagedWorkloads: " + updatedUnManagedWorkloads + " deletedWorkloads: " + deletedWorkloads);

                skippedWorkloads = totalWorkloads - createdUnknownWorkloads - updatedManagedWorkloads - updatedUnManagedWorkloads - deletedWorkloads - unpairedVens;
                this.logger._debug("IllumioUpdateWorkloads: Number of skipped workloads due to errors in the flow: " + skippedWorkloads);

                if (skippedWorkloads == totalWorkloads) {
                    // If no workloads are created/updated on PCE and ServiceNow
                    jobContent = {
                        job_status: JOB_STATUS_FAILED,
                        logs: 'Synchronization with PCE failed (All workloads skipped)',
                        job_completed: this.snowDateFormat.format(new Date()) + "",
                    };
                } else {
                    // One line, in the same shape as the instance-side "Summary:" that closes
                    // phase 2 and as the deletion branch's closing line. The block this replaces
                    // restated under headings, after a rule, numbers the Batch lines above have
                    // already given -- and did it identically in both arms of this branch, which
                    // differed only in the status they set.
                    var totalSkipped = skippedWorkloads + skippedWl;
                    jobContent = {
                        job_status: skippedWorkloads != 0 ? JOB_STATUS_COMPLETED_WITH_ERROR :
                            (this.partialSucc == 'true' ? 'partial_success' : 'completed'),
                        logs: 'Sync complete: ' + createdUnknownWorkloads + ' for creation, ' +
                            (updatedManagedWorkloads + updatedUnManagedWorkloads) +
                            ' for updation' +
                            (totalSkipped > 0 ? ', ' + totalSkipped + ' skipped' : '') +
                            this._since(syncStartedAt),
                        job_completed: this.snowDateFormat.format(new Date()) + "",
                        current_operation: 'Synchronization with PCE completed'
                    };
                }
                this._updateJobRecord(this.jobSysId, jobContent);
            } catch (exception) {
                this.logger._except("IllumioUpdateWorkloads: Exception while updating or creating workload on PCE : " + exception);
                jobContent = {
                    job_status: JOB_STATUS_FAILED,
                    logs: "Exception while updating or creating workload on PCE : " + exception,
                    job_completed: this.snowDateFormat.format(new Date()) + "",
                };
                this._updateJobRecord(this.jobSysId, jobContent);
            }
        }

        if (this.operation == "delete") {
            try {
                var deletedWorkloads = 0;
                var unpairedVens = 0;
                var totalWorkloads = 0;
                var skippedDeletion = parseInt(this.skipped) || 0;

                // P0-1: the workloads arrive in deletion payload rows now rather than inside
                // the ECC message, which used to carry both lists as JSON and grew with the
                // number of matched workloads. Rows are read and deleted one at a time, the same
                // way the updateCreate branch above consumes autosync payload rows.
                //
                // R33: the row sys_ids are queried by job rather than read out of the message,
                // for the reason on _payloadRowSysIds -- the list was the last thing in the ECC
                // record that grew with the size of the run.
                //
                // Unpair and delete are disjoint sets -- a managed workload unpairs its VEN, an
                // unmanaged one is deleted -- so doing both inside each row rather than all
                // unpairs before all deletes reorders nothing that depends on the other.
                var deletionRowSysIds = this._payloadRowSysIds(DELETION_PAYLOAD_TABLE);

                // The counterpart of the updateCreate guard above, and the reason this failure
                // was unreadable. With no rows the loop below does nothing, every counter stays
                // at zero, and the closing block then writes "Deletion completed / Deleted
                // workloads: 0" onto a job it has just set to `failed` -- a log that contradicts
                // its own status and names nothing to look at.
                if (deletionRowSysIds.length === 0) {
                    this.logger._error('[delete] No payload rows found for job ' + this.jobSysId +
                        '. Nothing was sent to the PCE.');
                    this._updateJobRecord(this.jobSysId, {
                        job_status: JOB_STATUS_FAILED,
                        logs: 'No deletion payload rows could be found for this job, so nothing ' +
                            'was sent to the PCE. The workloads were prepared but the MID ' +
                            'Server could not read them back.',
                        job_completed: this.snowDateFormat.format(new Date()) + ''
                    });
                    return;
                }

                // A batch is a payload row: one row is IllumioSyncUtils.PAYLOAD_ROW_SIZE
                // workloads, sized to be one PCE bulk call. Known before the first row is read,
                // so "Batch 3/10" carries a true denominator.
                //
                // This used to be numbered inside the row, against the chunks a row was cut into
                // by batch_size. With batch_size at its default the cut is a no-op, so every row
                // logged "batch 1 of 1" -- ten identical lines telling the operator nothing about
                // where the run had got to.
                var totalBatches = deletionRowSysIds.length;
                var deletionStartedAt = new Date().getTime();

                for (var pr = 0; pr < deletionRowSysIds.length; pr++) {
                    var batchLabel = 'Batch ' + (pr + 1) + '/' + totalBatches;
                    var deletionRowSysId = deletionRowSysIds[pr];
                    if (!deletionRowSysId) {
                        continue;
                    }

                    var rowStartedAt = new Date().getTime();
                    var rowUnpairAttempted = 0,
                        rowUnpaired = 0,
                        rowDeleteAttempted = 0,
                        rowDeleted = 0;

                    var deletionPayload = this._readPayloadRow(
                        DELETION_PAYLOAD_TABLE, deletionRowSysId);

                    // Skipped rather than aborted. Each row is an independent set of workloads,
                    // so one unreadable row costs those workloads and nothing else; failing the
                    // whole job would leave the rows already sent to the PCE deleted there and
                    // the job saying it did nothing.
                    //
                    // Logged as a batch rather than passed over silently: the numbering runs to
                    // totalBatches either way, and a gap in it would read as a lost line.
                    if (!deletionPayload) {
                        this._updateJobRecord(this.jobSysId, {
                            logs: batchLabel + ': skipped, payload row could not be read'
                        });
                        continue;
                    }

                    this.snHttpClient.deleteMethod(
                        TABLE_API + DELETION_PAYLOAD_TABLE + '/' + deletionRowSysId,
                        ''
                    );

                    var vensToUnpair = deletionPayload.vensToUnpair || [];
                    if (vensToUnpair.length > 0) {
                        this.logger._debug("Unpairing " + vensToUnpair.length + " VEN(s) before deletion");
                        totalWorkloads += vensToUnpair.length;
                        rowUnpairAttempted = vensToUnpair.length;

                        var unpairUrl = "/api/v2/orgs/" + this.pceOrgId + "/vens/unpair";
                        var unpairChunks = [];
                        var ui;
                        for (ui = 0; ui < vensToUnpair.length; ui += this.batchSize) {
                            unpairChunks.push(vensToUnpair.slice(ui, ui + this.batchSize));
                        }

                        for (var ub = 0; ub < unpairChunks.length; ub++) {
                            if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                                this.logger._debug("[unpair]: Job is cancelled");
                                return;
                            }

                            // Syslog, not the job record. This is the cut WITHIN a row, made by
                            // batch_size; the job record's unit is the row, reported once below.
                            this.logger._debug('Unpairing VENs - chunk ' + (ub + 1) + ' of ' +
                                unpairChunks.length + ' (' + unpairChunks[ub].length + ' VENs)');
                            this._updateJobRecord(this.jobSysId, {
                                current_operation: 'Unpairing VENs (' + batchLabel + ')'
                            });

                            var unpairBody = {
                                "vens": unpairChunks[ub].map(function(venHref) {
                                    return {"href": venHref};
                                }),
                                "firewall_restore": "default"
                            };

                            var unpairResponse = this.pceHttpClient.put(unpairUrl, '', null, unpairBody);
                            if (unpairResponse.hasError) {
                                this.logger._error("IllumioUpdateWorkloads: Failed to unpair VENs (batch " + (ub + 1) + "). Response status code: " + unpairResponse.status);
                                jobContent = {
                                    job_status: JOB_STATUS_FAILED,
                                    logs: 'Failed to unpair VENs (batch ' + (ub + 1) + '). Response status code: ' + unpairResponse.status,
                                    job_completed: this.snowDateFormat.format(new Date()) + ""
                                };
                                this._updateJobRecord(this.jobSysId, jobContent);
                                return;
                            }
                            this.logger._debug("Successfully unpaired chunk " + (ub + 1) + ": " + unpairChunks[ub].length + " VEN(s)");
                            unpairedVens += unpairChunks[ub].length;
                            rowUnpaired += unpairChunks[ub].length;
                        }
                    }

                    var retiredWorkloads = deletionPayload.retiredWorkloads || {};
                    var allHref = [];
                    for (var hrefKey in retiredWorkloads) {
                        allHref.push({"href": hrefKey});
                    }
                    totalWorkloads += allHref.length;
                    rowDeleteAttempted = allHref.length;

                    if (allHref.length > 0) {
                        var deleteUrl = "/api/v2/orgs/" + this.pceOrgId + "/workloads/bulk_delete";
                        var deleteChunks = [];
                        var di;
                        for (di = 0; di < allHref.length; di += this.batchSize) {
                            deleteChunks.push(allHref.slice(di, di + this.batchSize));
                        }

                        var notDeletedWorkloads = 0;
                        for (var db = 0; db < deleteChunks.length; db++) {
                            if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                                this.logger._debug("[delete]: Job is cancelled");
                                return;
                            }

                            // Syslog, not the job record. This is the cut WITHIN a row, made by
                            // batch_size; the job record's unit is the row, reported once below.
                            this.logger._debug('Deleting workloads from PCE - chunk ' + (db + 1) +
                                ' of ' + deleteChunks.length + ' (' + deleteChunks[db].length +
                                ' workloads)');
                            this._updateJobRecord(this.jobSysId, {
                                current_operation: 'Deleting workloads (' + batchLabel + ')'
                            });

                            var deleteResponse = this.pceHttpClient.put(deleteUrl, '', null, deleteChunks[db]);
                            if (deleteResponse.hasError) {
                                this.logger._error("IllumioUpdateWorkloads: Failed to delete workloads (batch " + (db + 1) + "). Response status code: " + deleteResponse.status);
                                jobContent = {
                                    job_status: JOB_STATUS_FAILED,
                                    logs: 'Failed to delete workloads (batch ' + (db + 1) + '). Response status code: ' + deleteResponse.status,
                                    job_completed: this.snowDateFormat.format(new Date()) + ""
                                };
                                this._updateJobRecord(this.jobSysId, jobContent);
                                return;
                            }

                            if (deleteResponse.data && deleteResponse.data.length) {
                                for (var dr = 0; dr < deleteResponse.data.length; dr++) {
                                    notDeletedWorkloads++;
                                    this.logger._error("IllumioUpdateWorkloads: Failed to delete workload: " + deleteResponse.data[dr]["href"]);
                                }
                            }
                            this.logger._debug("Delete chunk " + (db + 1) + " complete: " + deleteChunks[db].length + " sent");
                        }
                        deletedWorkloads += allHref.length - notDeletedWorkloads;
                        rowDeleted = allHref.length - notDeletedWorkloads;
                    }

                    // The row's one line. Deleted and unpaired are disjoint -- a managed workload
                    // unpairs its VEN, an unmanaged one is deleted -- so the unpair clause is
                    // omitted rather than shown as 0/0 on the runs that only delete.
                    var batchLine = batchLabel + ': ' + rowDeleted + '/' + rowDeleteAttempted +
                        ' deleted';
                    if (rowUnpairAttempted > 0) {
                        batchLine += ', ' + rowUnpaired + '/' + rowUnpairAttempted + ' unpaired';
                    }
                    // W2: per-batch, so syslog rather than the job record -- same reasoning as the
                    // sync loop's row line. The Deletion complete line below carries the totals.
                    this.logger._milestone(batchLine + this._since(rowStartedAt));
                }

                var failedWorkloads = totalWorkloads - deletedWorkloads - unpairedVens;
                var status = this.partialSucc == 'true' ? JOB_STATUS_PARTIAL_SUCCESS : JOB_STATUS_COMPLETED;
                if (failedWorkloads > 0) {
                    status = JOB_STATUS_COMPLETED_WITH_ERROR;
                }
                if (deletedWorkloads === 0 && unpairedVens === 0) {
                    status = JOB_STATUS_FAILED;
                }

                // One line, in the same shape as the instance-side "Summary:" that closes phase 2.
                // The block this replaces restated three numbers the Batch lines above had
                // already given, under headings, after a rule -- and its "Skipped" was the only
                // figure in it that was not already on the record.
                var totalSkipped = failedWorkloads + skippedDeletion;
                jobContent = {
                    job_status: status,
                    logs: 'Deletion complete: ' + deletedWorkloads +
                        ' workload(s) for deletion, ' + unpairedVens +
                        ' workload(s) for unpair' +
                        (totalSkipped > 0 ? ', ' + totalSkipped + ' skipped' : '') +
                        this._since(deletionStartedAt),
                    current_operation: 'Deletion completed',
                    job_completed: this.snowDateFormat.format(new Date()) + ""
                };
                this._updateJobRecord(this.jobSysId, jobContent);

            } catch (exception) {
                this.logger._except("IllumioUpdateWorkloads: Exception during deletion: " + exception);
                jobContent = {
                    job_status: JOB_STATUS_FAILED,
                    logs: "Exception during deletion: " + exception,
                    job_completed: this.snowDateFormat.format(new Date()) + ""
                };
                this._updateJobRecord(this.jobSysId, jobContent);
            }
        }
    },

    /**
     * Create the required workloads on the PCE
     * @param {Array} payload list of payload to create on pce.
     * @return {JSON} Object with status and count of workload created.
     */
    /**
     * Record why one workload was dropped, grouped by reason.
     *
     * Every `continue` in create()/update(), and every bulk-response entry that came back with
     * a status other than created/updated, used to go to ms.log and nowhere else. The job record
     * saw only the arithmetic residual
     * (total - created - updated - deleted - unpaired), which can say "428 skipped" without
     * saying that any of the 428 had a stated reason. This keeps the reason.
     *
     * @param {Object} bag    Reason -> count
     * @param {String} reason Short groupable phrase -- never a hostname or a sys_id, or the
     *                        tally degenerates into one line per workload.
     */
    _tallyDrop: function(bag, reason) {
        bag[reason] = (bag[reason] || 0) + 1;
    },

    /**
     * Reduce one bulk_create/bulk_update response entry to a short, groupable reason.
     *
     * The PCE is not consistent here: some rejections carry `message`, some carry an `errors`
     * array of {token, message}. Anything that varies per workload (a hostname in the text, for
     * instance) would defeat the grouping, so the result is truncated.
     *
     * @param {Object} entry One element of the bulk response array
     * @return {String}
     */
    _describeBulkError: function(entry) {
        var text = '';
        if (entry.errors && entry.errors.length > 0) {
            var parts = [];
            for (var e = 0; e < entry.errors.length; e++) {
                parts.push(entry.errors[e].token || entry.errors[e].message || '');
            }
            text = parts.join(', ');
        } else {
            text = entry.message || entry.status || 'no reason given';
        }
        text = ('' + text).replace(/\s+/g, ' ');
        return text.length > 120 ? text.substring(0, 120) + '...' : text;
    },

    /**
     * Render a drop tally as job-log lines, commonest reason first.
     * @param {Object} bag Reason -> count, as built by _tallyDrop
     * @return {String} Empty string when nothing was dropped
     */
    _renderDrops: function(bag) {
        var reasons = [],
            reason;
        for (reason in bag) {
            if (bag.hasOwnProperty(reason)) {
                reasons.push([reason, bag[reason]]);
            }
        }
        if (reasons.length === 0) {
            return '';
        }
        reasons.sort(function(a, b) {
            return b[1] - a[1];
        });
        var lines = [];
        for (var r = 0; r < reasons.length; r++) {
            lines.push('   ' + reasons[r][1] + ' x ' + reasons[r][0]);
        }
        return lines.join('\n');
    },

    /**
     * Write a drop breakdown onto the job record, if anything was dropped.
     * @param {String} verb     'create' or 'update', for the wording
     * @param {String} noun     What was being processed, e.g. 'unknown workload(s)'
     * @param {Number} attempted How many went in
     * @param {Object} result   Return value of create()/update()
     */
    _logDrops: function(verb, noun, attempted, result) {
        if (!result) {
            return;
        }
        var rendered = this._renderDrops(result.dropped || {});
        if (!rendered) {
            return;
        }
        var succeeded = result.count || 0;
        this._updateJobRecord(this.jobSysId, {
            logs: 'Could not ' + verb + ' ' + (attempted - succeeded) + ' of ' + attempted +
                ' ' + noun + ':\n' + rendered
        });
    },

    create: function(payload) {

        this.logger._info("IllumioUpdateWorkloads: Initiating creating the workloads on PCE");
        var labelsToUse, hostname, public_ip, created_workloads = 0,
            sys_id;
        var dropped = {};
        // R34: accepts the array directly from updateCreate, or a JSON string on the
        // single-workload `create` operation, which reads its payload straight off the ECC
        // message parameter and has no array to hand.
        var payloadList = typeof payload === 'string' ? JSON.parse(payload) : payload;

        var payloadBody = [];
        // R34: this array MUST stay -- it is index-aligned with payloadBody, and that alignment
        // is how a per-item PCE bulk_create response maps back to a workload further down
        // (snowUpdateQueue_chunked[i][putResponseIndex]). What it carries shrank to `hostname`,
        // the only property anything reads. The write-back fields it used to hold -- sys_id,
        // public_ip, labels, interfaces and the payloadPut bag -- are gone: nothing in this repo
        // has ever read payloadPut, because post-sync discovery rebuilds the ServiceNow tables
        // rather than the MID writing them back.
        var snowUpdateQueue = [];

        // Filtered list acc to workloads status after PCE REST Call

        for (var payloadIndex = 0; payloadIndex < payloadList.length; payloadIndex++) {
            public_ip = '';
            payload = payloadList[payloadIndex];

            // Skip processing the workload if custom record's sys_id is not known
            if (payload.sys_id) {
                sys_id = payload.sys_id;
            } else {
                this.logger._debug("IllumioUpdateWorkloads: Sys ID not found in the payload object : SKIPPED");
                this._tallyDrop(dropped, 'no sys_id in the payload object');
                continue;
            }

            var description = payload.description;
            var labelsToCreate = payload.createlabels;

            labelsToUse = payload.labels;
            hostname = payload.hostname;
            this.interfaces = payload.interfaces;
            if (payload.ip_address != undefined && payload.ip_address != "") {
                if (payload.ip_address.match(this.VALID_IP_REGEX)) {
                    public_ip = payload.ip_address;
                } else {
                    this.logger._error('Skipped creating workload ' + payload.hostname + ' as the IP Address ' + payload.ip_address + ' is invalid.');
                    this._tallyDrop(dropped, 'invalid IP address on the ServiceNow record');
                    continue;
                }
            }

            // R34: was { sys_id, hostname, public_ip, payloadPut: {} }. Only `hostname` is ever
            // read back (the success count and debug line below the bulk_create).
            var snowUpdateObject = {
                "hostname": hostname
            };

            if (labelsToCreate.length > 0) {
                this.logger._debug("IllumioUpdateWorkloads: Creating required labels");
            }
            if (!this.createLabels(labelsToCreate, labelsToUse)) {
                this.logger._error("IllumioUpdateWorkloads: Failed to Create workload. Reason : Failed to create required labels");
                this._tallyDrop(dropped, 'required label(s) could not be created on the PCE');
                continue;
            }

            var workloadBody = {
                "labels": labelsToUse,
                "hostname": hostname,
                "description": description
            };

            if (public_ip != "" && public_ip != undefined) {
                workloadBody.public_ip = public_ip;
            }
            workloadBody.interfaces = this.interfaces.length > 0 ? this.interfaces : [];
            payloadBody.push(workloadBody);

            // R34: the workload is fully prepared for the PCE at the push above. Everything that
            // used to follow built `payloadPut`, the write-back bag for the ServiceNow Workload
            // Field Value table -- and nothing in this repo has ever read it. The MID stopped
            // writing back when post-sync discovery took over rebuilding those tables; the
            // builders were left behind. `grep -rn "payloadPut" Illumio/src` was ten writes and
            // zero reads.
            //
            // Removing it also removes the only caller of getLabelDetails, and with it the
            // ~100k-row PCE Labels Mapping read and the run-long labelDetails map it filled.
            // Nothing here was needed for the PCE: `labels` is already complete on workloadBody
            // (the instance resolved it, and createLabels appended any it had to create).
            //
            // snowUpdateObject["payloadPut"]["interfaces"] = JSON.stringify({
            //     "umw0": { "pce_value": "", "cmdb_value": "" }
            // });
            // snowUpdateObject["labels"] = labelsToUse;
            //
            // for (var label_index = 0, label_length = labelsToUse.length; label_index < label_length; label_index++) {
            //     var label, labelDetails, key, value;
            //     label = labelsToUse[label_index];
            //     labelDetails = this.getLabelDetails(label);
            //     if (labelDetails) {
            //         key = labelDetails.key;
            //         value = labelDetails.value;
            //         snowUpdateObject.payloadPut[key] = value;
            //     } else {
            //         this.logger._error('Could not find label having href: ' + label.href);
            //     }
            // }
            // var interface_length = this.interfaces.length;
            // var snowInterface = {};
            // for (var interface_index = 0; interface_index < interface_length; interface_index++) {
            //     var interface_name = this.interfaces[interface_index].name;
            //     var interface_address = this.interfaces[interface_index].address;
            //     snowInterface[interface_name] = {};
            //     snowInterface[interface_name]['pce_value'] = interface_address;
            //     snowInterface[interface_name]['cmdb_value'] = interface_address;
            //     snowUpdateObject.payloadPut['interfaces'] = JSON.stringify(snowInterface);
            // }
            snowUpdateQueue.push(snowUpdateObject);
        }
        if (payloadBody.length == 0) {
            return {
                "exception": 'PCE. Check MID Server logs for details.',
                "count": 0,
                "dropped": dropped
            };
        }

        // Make the put call to create the workloads on PCE
        this.logger._debug("IllumioUpdateWorkloads: Making PUT call to create the workloads on PCE.");
        var payloadBody_chunked = [];
        var snowUpdateQueue_chunked = [];
        var payloadBody_length = payloadBody.length;
        var snowUpdateQueue_length = snowUpdateQueue.length;
        var myChunk, index;

        for (index = 0; index < payloadBody_length; index += this.batchSize) {
            myChunk = payloadBody.slice(index, index + this.batchSize);
            // Do something if you want with the group
            payloadBody_chunked.push(myChunk);
        }

        for (index = 0; index < snowUpdateQueue_length; index += this.batchSize) {
            myChunk = snowUpdateQueue.slice(index, index + this.batchSize);
            // Do something if you want with the group
            snowUpdateQueue_chunked.push(myChunk);
        }
        var payloadBody_chunked_length = payloadBody_chunked.length;
        for (var i = 0; i < payloadBody_chunked_length; i++) {

            if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                return;
            }

            this.logger._info("IllumioUpdateWorkloads: Creating workloads. Batch: " + (i + 1));
            var snowUpdateQueueFinal = [];
            var url = "/api/v2/orgs/" + this.pceOrgId + "/workloads/bulk_create";

            var putResponse = this.pceHttpClient.put(url, '', '', payloadBody_chunked[i]);
            this.logger._debug("Put Response Handler->", putResponse);
            if (putResponse.hasError) {
                this.logger._debug("IllumioUpdateWorkloads: Failed create the workloads on PCE.");
                this._tallyDrop(dropped, 'bulk_create batch ' + (i + 1) +
                    ' failed outright, HTTP ' + putResponse.status);
                return {
                    "status": false,
                    "count": created_workloads,
                    "exception": 'PCE. Response status code: ' + putResponse.status,
                    "dropped": dropped
                };
            }
            var putResponseObject = putResponse.data;

            for (var putResponseIndex = 0; putResponseIndex < putResponseObject.length; putResponseIndex++) {
                if (putResponseObject[putResponseIndex].status == "created") {
                    snowUpdateQueueFinal.push(snowUpdateQueue_chunked[i][putResponseIndex]);
                } else {
                    this.logger._error("IllumioUpdateWorkloads: Error while creating a workload : SKIPPED");
                    this.logger._error("IllumioUpdateWorkloads: Message : " + putResponseObject[putResponseIndex].message);
                    // The PCE answers bulk_create per item, so a 200 can still carry hundreds of
                    // rejections. Group by the message so the job log shows the reason once with
                    // a count, rather than 428 identical lines or -- as before -- none at all.
                    this._tallyDrop(dropped, 'PCE rejected the workload: ' +
                        this._describeBulkError(putResponseObject[putResponseIndex]));
                }
            }




            // SNOW tables will be refreshed by post-sync discovery — only count PCE successes
            for (var p = 0; p < snowUpdateQueueFinal.length; p++) {
                created_workloads++;
                this.logger._debug("IllumioUpdateWorkloads: Successfully created workload on PCE: " + snowUpdateQueueFinal[p].hostname);
            }
        }

        this.logger._info("IllumioUpdateWorkloads: Workload creation complete");
        return {
            "status": true,
            "count": created_workloads,
            "dropped": dropped
        };
    },

    /**
     * Process the list of payloads and upload them on PCE.
     * @param {Array} payload list of payload to upload on pce.
     * @return {JSON} Object with status and count of workload uploaded.
     */
    update: function(payload) {

        this.logger._info("IllumioUpdateWorkloads: Initiating updating the workloads on PCE ");

        var href, labelsToUse, updated_workloads = 0;
        var index;
        var dropped = {};
        // R34: accepts the array directly, or a JSON string. Same reason as create().
        var payloadList = typeof payload === 'string' ? JSON.parse(payload) : payload;

        var payloadBody = [];
        // R34: kept for its index alignment with payloadBody, shrunk to `hostname`. See the
        // fuller note in create().
        var snowUpdateQueue = [];

        // Prepare the payload with list of workloads to be updated
        for (var payloadIndex = 0; payloadIndex < payloadList.length; payloadIndex++) {

            payload = payloadList[payloadIndex];

            var workloadBody = {};
            var labelsToCreate = payload.createlabels;

            var description = payload.description;
            var sys_id;

            href = payload.href;
            labelsToUse = payload.labels;

            var snowUpdateObject = {};

            // Skip processing the workload if custom record's sys_id is not known
            if (payload.sys_id) {
                sys_id = payload.sys_id;
            } else {
                this.logger._debug("IllumioUpdateWorkloads: Sys ID not found in the payload object : SKIPPED");
                this._tallyDrop(dropped, 'no sys_id in the payload object');
                continue;
            }

            if (labelsToCreate.length > 0) {
                this.logger._debug("IllumioUpdateWorkloads: Creating required labels.");
            }
            if (!this.createLabels(labelsToCreate, labelsToUse)) {

                // Create the unknown labels
                this.logger._error("IllumioUpdateWorkloads: Failed to update workload. Reason : Failed to create required labels " + href);
                this._tallyDrop(dropped, 'required label(s) could not be created on the PCE');
                continue;
            }
            // R34: was sys_id / href / labels / hostname / payloadPut. Only `hostname` is ever
            // read back. See the fuller note in create().
            snowUpdateObject["hostname"] = payload.hostname;

            workloadBody["href"] = href;
            workloadBody["labels"] = labelsToUse;
            workloadBody["description"] = description;

            if ("known_to_pce" in payload && payload.known_to_pce == "unmanaged") {
                if ("interfaces" in payload) {
                    var interfaces;
                    if (!payload.interfaces || payload.interfaces.length == 0) {
                        interfaces = [];

                    } else {
                        interfaces = payload.interfaces;
                    }
                    workloadBody["interfaces"] = interfaces;
                    // R34: the loop survives only to find umw0 for workloadBody.public_ip, which
                    // the PCE needs. snowUpdateObject["interfaces"] and the snowInterface builder
                    // that stood here fed payloadPut and are gone -- see the note in create().
                    var interfacesLength = interfaces.length;
                    for (index = 0; index < interfacesLength; index++) {
                        if (interfaces[index].name == "umw0" && interfaces[index].address != undefined && interfaces[index].address != "") {
                            workloadBody["public_ip"] = interfaces[index].address;
                        }
                    }
                }
            }
            // Add the object to the list in payload
            payloadBody.push(workloadBody);

            // R34: the workload is fully prepared for the PCE at the push above. Two blocks used
            // to follow, both building `payloadPut` and both dead -- nothing reads it:
            //
            //   1. blanking every mapped dimension, so the write-back would clear a field whose
            //      label had been removed;
            //   2. resolving each href back to (key, value) via getLabelDetails to refill them.
            //
            // (2) was the only caller of getLabelDetails, and so the only reason the ~100k-row
            // PCE Labels Mapping table was read into the run-long labelDetails map at all.
            //
            // if (payload.updateFields) {
            //     var updateFieldsLen = payload.updateFields.length;
            //     for (var updateFieldCount = 0; updateFieldCount < updateFieldsLen; updateFieldCount++) {
            //         snowUpdateObject.payloadPut[payload.updateFields[updateFieldCount]] = "";
            //     }
            // }
            //
            // for (var labelsToUse_i = 0; labelsToUse_i < labelsToUse.length; labelsToUse_i++) {
            //     var label, labelDetails, key, value;
            //     label = labelsToUse[labelsToUse_i];
            //     labelDetails = this.getLabelDetails(label);
            //     if (labelDetails) {
            //         key = labelDetails.key;
            //         value = labelDetails.value;
            //         if (payload.updateFields.indexOf(key) > -1)
            //             snowUpdateObject.payloadPut[key] = value;
            //     } else {
            //         this.logger._error('Could not find label having href: ' + label.href);
            //     }
            // }

            snowUpdateQueue.push(snowUpdateObject);
        }

        if (payloadBody.length == 0) {
            return {
                "exception": 'PCE. Check MID Server logs for details.',
                "count": 0,
                "dropped": dropped
            };
        }

        var payloadBody_chunked = [];
        var snowUpdateQueue_chunked = [];
        var payloadBody_length = payloadBody.length;
        var snowUpdateQueue_length = snowUpdateQueue.length;
        var myChunk;

        for (index = 0; index < payloadBody_length; index += this.batchSize) {
            myChunk = payloadBody.slice(index, index + this.batchSize);
            // Do something if you want with the group
            payloadBody_chunked.push(myChunk);
        }

        for (index = 0; index < snowUpdateQueue_length; index += this.batchSize) {
            myChunk = snowUpdateQueue.slice(index, index + this.batchSize);
            // Do something if you want with the group
            snowUpdateQueue_chunked.push(myChunk);
        }
        var payloadBody_chunked_length = payloadBody_chunked.length;
        for (var i = 0; i < payloadBody_chunked_length; i++) {


            if (this.utils.checkCancelledJobStatus(this.jobSysId)) {
                return;
            }

            this.logger._info("IllumioUpdateWorkloads: Updating workloads. Batch: " + (i + 1));

            var snowUpdateQueueFinal = []; // Filtered list acc to workloads status after PCE REST Call

            var url = "/api/v2/orgs/" + this.pceOrgId + "/workloads/bulk_update";
            var putResponse = this.pceHttpClient.put(url, '', '', payloadBody_chunked[i]);

            // If the PUT call failed
            if (putResponse.hasError) {
                this.logger._error("IllumioUpdateWorkloads: Failed to update the workload on PCE.");
                this._tallyDrop(dropped, 'bulk_update batch ' + (i + 1) +
                    ' failed outright, HTTP ' + putResponse.status);
                return {
                    "status": false,
                    "count": updated_workloads,
                    "exception": 'PCE. Response status code: ' + putResponse.status,
                    "dropped": dropped
                };
            }

            var putResponseObject = putResponse.data;
            // Create the final SNOW update payload by filtering payloads from failed operations
            for (var putResponseIndex = 0; putResponseIndex < putResponseObject.length; putResponseIndex++) {
                if (putResponseObject[putResponseIndex].status == "updated") {
                    snowUpdateQueueFinal.push(snowUpdateQueue_chunked[i][putResponseIndex]);
                } else {
                    this.logger._error("IllumioUpdateWorkloads: Failed to update a workload on PCE : " + putResponseObject[putResponseIndex].message);
                    this._tallyDrop(dropped, 'PCE rejected the workload: ' +
                        this._describeBulkError(putResponseObject[putResponseIndex]));
                }
            }

            // SNOW tables will be refreshed by post-sync discovery — only count PCE successes
            for (var p = 0; p < snowUpdateQueueFinal.length; p++) {
                updated_workloads++;
                this.logger._debug("IllumioUpdateWorkloads: Successfully updated workload on PCE: " + snowUpdateQueueFinal[p].hostname);
            }
        }

        this.logger._info("IllumioUpdateWorkloads: Workload updation complete");
        return {
            "status": true,
            "count": updated_workloads,
            "dropped": dropped
        };
    },
    /**	* Receive the list of labels to create and the labels to use.
     * Create the required labels and push them to the list of  labels to be used.
     * @param {String} labelsToCreate labels to create.
     * @param {String} labelsToUse labels to use.
     * @return {Boolean} labels were successfully created or not.
     */
    createLabels: function(labelsToCreate, labelsToUse) {
        for (var l = 0, labelLen = labelsToCreate.length; l < labelLen; l++) {
            var label = labelsToCreate[l];
            var storedLabelValue = label.value + "";

            // If the label was created recently use that instead of attempting to create again
            if (this.newLabelsCreated[label.key] && this.newLabelsCreated[label.key][label.value]) {
                this.logger._debug("Label already exist : " + label.key + " -> " + label.value);
                labelsToUse.push(this.newLabelsCreated[label.key][label.value]);
                continue;
            }
            // Make the HTTP call to create new the label
            var url = "/api/v2/orgs/" + this.pceOrgId + "/labels/";
            this.logger._debug("Creating Label: " + JSON.stringify(label));
            var response = this.pceHttpClient.post(url, '', null, label);
            if (response.hasError && response.status != 406) {
                this.logger._error("IllumioUpdateWorkloads: Error while creating label -> " + label.key + " : " + label.value);
                return false;
            }

            var status = response.status;
            var respBody = response.data;

            // If the label was created successfully
            if (status == "201" || status == "406") {

                if (status == "406") {
                    this.logger._debug("IllumioUpdateWorkloads: Label is already exist on PCE -> " + label.key + " : " + label.value);
                    this.logger._debug("IllumioUpdateWorkloads: Fetching label details from PCE -> " + label.key + " : " + label.value);
                    url = "/api/v2/orgs/" + this.pceOrgId + "/labels";
                    var queryString = "key=" + encodeURIComponent(label.key) + "&value=" + encodeURIComponent(label.value);
                    var labelDetails = this.pceHttpClient.get(url, queryString);
                    respBody = null;
                    if (!labelDetails.hasError) {
                        for (var item in labelDetails.data) {
                            if (labelDetails.data[item].key == label.key && (labelDetails.data[item].value + '').toLowerCase() == (label.value + '').toLowerCase()) {
                                respBody = labelDetails.data[item];
                                break;
                            }
                        }
                    } else {
                        this.logger._error("IllumioUpdateWorkloads: Error while fetching label from PCE. Status : " + labelDetails.status);
                        return false;
                    }
                    if (respBody == null) {
                        this.logger._error("IllumioUpdateWorkloads: Could not find label on PCE -> " + label.key + " : " + label.value);
                        return false;
                    }
                } else {
                    this.logger._info("Created label -> " + label.key + " : " + label.value);
                }
                // Append to the list of recently created labels.
                //
                // Only initialise the bucket when it is absent. It used to be reassigned to {} on
                // every create, which discarded every other value already cached under the same
                // key -- so the cache held exactly one value per dimension and a run with several
                // roles interleaved across workloads re-POSTed /labels/ for a value it had
                // already created, got 406 "already exists", and followed it with a GET to look
                // the href back up. Two PCE calls per workload per dimension instead of one per
                // distinct label, which is what produced enough traffic to earn a 429.
                if (!this.newLabelsCreated[label.key]) {
                    this.newLabelsCreated[label.key] = {};
                }
                this.newLabelsCreated[label.key][storedLabelValue] = {
                    "href": respBody.href
                };
                labelsToUse.push({
                    "href": respBody.href
                });
                // SNOW labels mapping will be refreshed by post-sync discovery
            } else {
                this.logger._error("IllumioUpdateWorkloads: Error while creating label. Status : " + status);
                return false;
            }
        }

        return true;
    },


    // R34: collectLabelDetails and getLabelDetails are retired together. They resolved a PCE
    // label href back to its (key, value) so that `payloadPut` could be built -- and payloadPut
    // was the MID's write-back to the ServiceNow Workload Field Value table, which post-sync
    // discovery replaced. Nothing reads it, so nothing needs this.
    //
    // Why this mattered enough to name: collectLabelDetails was called once from updateCreate
    // with no href, which made it an unfiltered, unprojected, unlimited GET of the whole PCE
    // Labels Mapping table for the configuration -- ~100k rows in production. It ran OUTSIDE the
    // payload-row loop, so no amount of windowing could have bounded it, and the map it filled
    // (this.labelDetails) was never cleared. Objective 3's only leak and objective 2's item 3
    // were the same object. Only the Table API's 10,000-row default kept it from landing whole,
    // which also meant the cache silently missed on an arbitrary 90% of the table and quietly
    // fell through to the per-href and then per-PCE-call paths below.
    //
    // Do NOT reinstate these to "look up a label on the MID". The MID needs no label data from
    // ServiceNow: the payload arrives with `labels` (hrefs the instance resolved) and
    // `createlabels` (what must be made), and createLabels appends the hrefs it mints. That is
    // the complete set the PCE needs, and nothing goes back.
    //
    // collectLabelDetails: function(href) {
    //     var labelGetUrl =
    //         TABLE_API +
    //         PCE_LABELS_MAPPING_TABLE +
    //         '?illumio_pce_configuration=' +
    //         this.configSysId;
    //     if (href) {
    //         labelGetUrl = labelGetUrl + '&href=' + href;
    //     }
    //
    //     var response = this.snHttpClient.get(labelGetUrl, '');
    //     if (response.data.result.length == 0) {
    //         this.logger._error('No Results Found for the Query');
    //         return false;
    //     }
    //     var labelMappingRecords = response.data.result;
    //
    //     for (var i = 0; i < labelMappingRecords.length; i++) {
    //         var mappingRecord = labelMappingRecords[i];
    //         this.labelDetails[mappingRecord.href] = {
    //             key: mappingRecord.key + '',
    //             value: mappingRecord.value + '',
    //         };
    //     }
    // },
    //
    // getLabelDetails: function(label) {
    //     if (this.labelDetails[label.href]) {
    //         return this.labelDetails[label.href];
    //     }
    //     this.collectLabelDetails(label.href);
    //     if (this.labelDetails[label.href]) {
    //         return this.labelDetails[label.href];
    //     }
    //
    //     var url = "/api/v2" + label.href;
    //     var labelDetails = this.pceHttpClient.get(url);
    //
    //     if (!labelDetails.hasError) {
    //         this.labelDetails[label.href] = {};
    //         this.labelDetails[label.href]['key'] = labelDetails.data.key;
    //         this.labelDetails[label.href]['value'] = labelDetails.data.value;
    //         return this.labelDetails[label.href];
    //     }
    //     return null;
    // },
    /**
     * Check if job is invalidated or not
     * @return {Boolean} running job was invalidated or not.
     */
    _checkInvalidatedJob: function() {

        var snowGetUrl =
            TABLE_API +
            SCHEDULED_JOB_TABLE +
            '?sysparm_query=sys_id=' + this.jobSysId +
            // W1: was an unqualified GET -- no sysparm_fields, so it pulled back the WHOLE job
            // record including `logs`, which grows for the length of the run. Asking "is this job
            // still valid?" cost more with every line the job had already written.
            '&sysparm_fields=job_status' +
            '&sysparm_limit=1';

        var response = this.snHttpClient.get(snowGetUrl, '');
        if (response.hasError || !response.data || !response.data.result ||
            response.data.result.length === 0) {
            this.logger._error('No Results Found for the Query');
            return false;
        }
        var jobRecord = response.data.result[0];
        if (jobRecord.job_status == JOB_STATUS_INVALIDATED) {
            this.logger._debug(
                '[run] Given job is invalidated. Aborting further actions.'
            );
            return true;
        } else if (jobRecord.job_status == JOB_STATUS_CANCELLED) return false;

    },

    /**
     * Updates scheduled job record with given parameters.
     *
     * One GET, one PUT, and the PUT carries only the fields that changed.
     *
     * W1 collapsed three round trips into two. It used to call _checkInvalidatedJob() -- an
     * unqualified GET that returned the whole record, `logs` included -- then GET `logs` again,
     * then PUT the entire record back. Both reads carried the accumulated log string across the
     * network, so the cost of writing one line rose with every line already written; on a 100k
     * run that is tens of megabytes of log moved for no reason. The invalidation check is folded
     * into the single GET below, which now asks for `job_status` as well.
     *
     * Two things went with the whole-record PUT and are worth naming, because both were defects
     * rather than style:
     *
     *  - `jobRecord.illumio_pce_configuration.value` was dereferenced on a record fetched with
     *    `sysparm_fields=logs`, so that field was never in the response. It existed only to
     *    re-flatten a reference field for a PUT that no longer sends it.
     *  - `String.replaceAll` is ES2021 and the MID runs Rhino. The same unescaping is done below
     *    with `.replace(/../g, ..)`, which is ES5 and does the same job.
     *
     * @param {String} jobSysId sys_id of the job record
     * @param {Object} jobContent Fields to write. `logs` is appended to what is already there;
     *                 everything else is replaced.
     */
    _updateJobRecord: function(jobSysId, jobContent) {

        var snowGetUrl =
            TABLE_API +
            SCHEDULED_JOB_TABLE +
            '?sysparm_fields=logs,job_status&sysparm_query=sys_id=' + jobSysId +
            '&sysparm_limit=1';

        var putUrl = TABLE_API + SCHEDULED_JOB_TABLE + '/' + jobSysId;

        var response = this.snHttpClient.get(snowGetUrl, '');
        if (response.hasError || !response.data || !response.data.result ||
            response.data.result.length === 0) {
            this.logger._error(
                '[_updateJobRecord] Error while checking status of given job on ServiceNow. ' +
                'Proceeding with further actions.'
            );
            return false;
        }

        var jobRecord = response.data.result[0];
        var status = String(jobRecord.job_status);

        // job_status was not in sysparm_fields before this, so all three of these comparisons
        // were against undefined: none of them ever fired, and a stopped job kept being written
        // to for as long as the probe ran.
        if (status == JOB_STATUS_INVALIDATED) {
            this.logger._debug('[_updateJobRecord] Given job is invalidated. Aborting further actions.');
            return true;
        }
        if (CANCELLED_JOB_STATUSES.indexOf(status) > -1) {
            return true;
        }
        if (status == JOB_STATUS_FAILED) {
            this.logger._info('[_updateJobRecord] Given job has already failed. Aborting further actions.');
            return false;
        }

        var payload = {};
        for (var key in jobContent) {
            if (jobContent.hasOwnProperty(key) && key != 'logs') {
                payload[key] = jobContent[key];
            }
        }

        if (jobContent.hasOwnProperty('logs')) {
            var existingLogs = String(jobRecord.logs == null ? '' : jobRecord.logs)
                .replace(/\\"/g, '"')
                .replace(/\\'/g, "'")
                .replace(/\\n/g, '\n');
            // W1: no per-line timestamp. The same line is emitted to syslog_app_scope, which
            // timestamps it there, and the job log is a milestone list rather than a trace.
            payload.logs = existingLogs + (existingLogs ? '\n' : '') + jobContent.logs;
            // W2: the job log and Application Logs carry the same milestones. Anything worth a
            // line on the job record is worth one in the correlated trail, where it sits next to
            // the MID-side detail that produced it. _milestone pushes it to the instance too, so
            // a job-log line and its surrounding context are readable from one place.
            this.logger._milestone(String(jobContent.logs));
        }

        var putResponse = this.snHttpClient.put(putUrl, '', null, payload);
        if (putResponse.hasError) {
            return false;
        }

        this.logger._debug('The Scheduled Job had updated the values with the logs');
    },

};
